package compose

import (
	"flag"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

var update = flag.Bool("update", false, "rewrite testdata/*.golden")

// The golden file was checked against the output of the original compose.py (only the "Generated by" comment differs).
func TestComposeGolden(t *testing.T) {
	root := t.TempDir()
	write(t, root, "base.json", `{"image":"docker.io/library/debian@sha256:`+strings.Repeat("a", 64)+`"}`)
	write(t, root, "kits/demo.json", `{"description":"Demo kit","apt_snapshot":"20261019T000000Z","features":["git","jq"]}`)
	for _, id := range []string{"git", "jq"} {
		write(t, root, "features/"+id+"/feature.json", `{"id":"`+id+`","description":"x"}`)
		write(t, root, "features/"+id+"/install.sh", "#!/usr/bin/env bash\napt-get install -y "+id+"\n")
	}
	got, err := Compose(root, "demo", "0123abc")
	if err != nil {
		t.Fatal(err)
	}
	golden := filepath.Join("testdata", "demo.golden")
	if *update {
		if err := os.WriteFile(golden, []byte(got), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile(golden)
	if err != nil {
		t.Fatal(err)
	}
	if got != string(want) {
		t.Errorf("Containerfile differs from %s (run with -update if intended):\n%s", golden, got)
	}
}

func TestComposeErrors(t *testing.T) {
	good := `{"description":"d","apt_snapshot":"20261019T000000Z","features":["git"]}`
	cases := map[string]struct{ kit, want string }{
		"bad snapshot":      {`{"apt_snapshot":"2026","features":["git"]}`, "apt_snapshot"},
		"no features":       {`{"apt_snapshot":"20261019T000000Z","features":[]}`, "non-empty list"},
		"duplicate feature": {`{"apt_snapshot":"20261019T000000Z","features":["git","git"]}`, "without duplicates"},
		"unknown feature":   {`{"apt_snapshot":"20261019T000000Z","features":["nope"]}`, "no install.sh"},
		"not an object":     {`[]`, "must be a JSON object"},
	}
	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			root := fixture(t, "debian@sha256:"+strings.Repeat("a", 64))
			write(t, root, "kits/k.json", c.kit)
			_, err := Compose(root, "k", "")
			if err == nil || !strings.Contains(err.Error(), c.want) {
				t.Fatalf("want error containing %q, got %v", c.want, err)
			}
		})
	}
	root := fixture(t, "debian@sha256:"+strings.Repeat("a", 64))
	write(t, root, "kits/k.json", good)
	write(t, root, "features/git/feature.json", `{"id":"other"}`)
	if _, err := Compose(root, "k", ""); err == nil || !strings.Contains(err.Error(), "another id") {
		t.Fatalf("want id mismatch error, got %v", err)
	}
	if _, err := Compose(root, "Bad_Name", ""); err == nil {
		t.Fatal("want error for kit name")
	}
}
